<?php
declare(strict_types=1);$active_module='agency_requests';require_once __DIR__.'/layout.php';if(empty($_SESSION['supplier_csrf']))$_SESSION['supplier_csrf']=bin2hex(random_bytes(32));$u=$supplier_user;$pdo=db();$message='';$error='';try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['supplier_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Güvenlik doğrulaması geçersiz.');$id=(int)$_POST['request_id'];$decision=$_POST['decision']==='approved'?'approved':'rejected';$q=$pdo->prepare('SELECT * FROM agency_discount_requests WHERE id=? AND supplier_id=? AND status=\'pending\' FOR UPDATE');$pdo->beginTransaction();$q->execute([$id,$u['supplier_id']]);$r=$q->fetch();if(!$r)throw new RuntimeException('Talep bulunamadı veya daha önce işlendi.');$approvedDiscount=($_POST['approved_discount']??'')===''?$r['requested_discount_percent']:(float)$_POST['approved_discount'];$approvedPrice=($_POST['approved_price']??'')===''?$r['requested_price']:(float)$_POST['approved_price'];$pdo->prepare('UPDATE agency_discount_requests SET status=?,approved_discount_percent=?,approved_price=?,approved_by=?,approved_at=now() WHERE id=?')->execute([$decision,$decision==='approved'?$approvedDiscount:null,$decision==='approved'?$approvedPrice:null,$u['id'],$id]);if($decision==='approved')$pdo->prepare('INSERT INTO agency_special_rates(agency_id,supplier_id,property_id,rate_plan_id,start_date,end_date,discount_percent,fixed_price,currency,request_id) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$r['agency_id'],$r['supplier_id'],$r['property_id'],$r['rate_plan_id'],$r['start_date'],$r['end_date'],$approvedDiscount,$approvedPrice,$r['currency'],$id]);$pdo->commit();$message='Talep işlendi.';}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}$q=$pdo->prepare("SELECT r.*,a.company_name agency_name,p.name property_name FROM agency_discount_requests r JOIN agencies a ON a.id=r.agency_id JOIN properties p ON p.id=r.property_id WHERE r.supplier_id=? ORDER BY CASE WHEN r.status='pending' THEN 0 ELSE 1 END,r.id DESC");$q->execute([$u['supplier_id']]);$rows=$q->fetchAll();supply_start('Acente indirim talepleri',$active_module);?><section class="page-intro"><p>Acentelerin özel fiyat ve indirim taleplerini onaylayın. Onaylanan tutar, talep tarihleri için acenteye özel satış kuralı olur.</p></section><?php if($message):?><p class="save-success">✓ <?=htmlspecialchars($message)?></p><?php endif;?><?php if($error):?><p class="login-error"><?=htmlspecialchars($error)?></p><?php endif;?><section class="next-module"><?php foreach($rows as $r):?><article><h2><?=htmlspecialchars($r['property_name'])?> · <?=htmlspecialchars($r['agency_name'])?></h2><p><?=htmlspecialchars($r['start_date'])?> / <?=htmlspecialchars($r['end_date'])?> · indirim talebi <?=htmlspecialchars($r['requested_discount_percent']??'—')?>% · hedef fiyat <?=htmlspecialchars($r['requested_price']??'—')?> <?=htmlspecialchars($r['currency']??'')?></p><p><?=htmlspecialchars($r['message']??'')?></p><?php if($r['status']==='pending'):?><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="request_id" value="<?=$r['id']?>"><div class="form-row"><label>Onay indirim %<input name="approved_discount" type="number" step="0.01" value="<?=htmlspecialchars($r['requested_discount_percent']??'')?>"></label><label>Onay hedef fiyat<input name="approved_price" type="number" step="0.01" value="<?=htmlspecialchars($r['requested_price']??'')?>"></label></div><button name="decision" value="approved">Onayla ve özel fiyat oluştur</button><button name="decision" value="rejected">Reddet</button></form><?php else:?><strong><?=htmlspecialchars($r['status'])?></strong><?php endif;?></article><?php endforeach;?></section><?php supply_end();
